CREATE COLUMN TABLE "TEST_AP"."FIX1" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50), "DprArea" NVARCHAR(15), "PeriodCat" NVARCHAR(10), "PostPeriod" INTEGER CS_INT, "RefDate" LONGDATE CS_LONGDATE, "APC" DECIMAL(21,6) CS_FIXED, "OrdDpr" DECIMAL(21,6) CS_FIXED, "UnpDpr" DECIMAL(21,6) CS_FIXED, "SpDprKey1" NVARCHAR(2), "SpDpr1" DECIMAL(21,6) CS_FIXED, "Qty" DECIMAL(21,6) CS_FIXED, "DprType" NVARCHAR(15), "DprDate" LONGDATE CS_LONGDATE, "RemLife" INTEGER CS_INT, "SalvageVal" DECIMAL(21,6) CS_FIXED, "RecvAsst" NVARCHAR(50), "RetirDate" LONGDATE CS_LONGDATE, "SpDprKey2" NVARCHAR(2), "SpDpr2" DECIMAL(21,6) CS_FIXED, "SpDprKey3" NVARCHAR(2), "TransType" NVARCHAR(4), "UsefulLife" INTEGER CS_INT, "Appr" DECIMAL(21,6) CS_FIXED, "WriteUp" DECIMAL(21,6) CS_FIXED, "DeltaDays" INTEGER CS_INT, "NewAstCls" NVARCHAR(20), "HistOrdDpr" DECIMAL(21,6) CS_FIXED, "SpDpr3" DECIMAL(21,6) CS_FIXED, "TransAmnt" DECIMAL(21,6) CS_FIXED, "Remark" NVARCHAR(254), "ReTranType" NVARCHAR(4) DEFAULT '0', "NewTtlUnit" INTEGER CS_INT, PRIMARY KEY ("AbsEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
